using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputDynamicsProof{
 static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[0]),before=File.ReadAllBytes(a[1]),pref=File.ReadAllBytes(a[2]),after=File.ReadAllBytes(a[3]);int count=BitConverter.ToInt16(ds,0x8798);var rows=new List<float[]>();for(int i=0;i<count;i++){var p=new float[15];Buffer.BlockCopy(before,i*60,p,0,60);rows.Add(p);}int[] symbols={53,55,57,52};for(int i=0;i<4;i++){int item=BitConverter.ToInt16(before,0x2b5c+i*2);rows.Add(InputDynamics.Create(symbols[i],rows[item-1],BitConverter.ToSingle(ds,0x8780),BitConverter.ToSingle(pref,16)));}int checks=0;for(int i=0;i<rows.Count;i++)for(int p=0;p<15;p++){if(BitConverter.ToInt32(BitConverter.GetBytes(rows[i][p]),0)!=BitConverter.ToInt32(after,i*60+p*4))throw new Exception("Record "+i+" P"+(p+1)+": "+rows[i][p]+" != "+BitConverter.ToSingle(after,i*60+p*4));checks++;}Console.WriteLine("PASS "+checks+" original dynamic-mark working words");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
